WITH parsed AS (SELECT id, host, level, status_code, payload_json, SIZE(context) AS num_context, context['version'] AS version FROM app_logs WHERE status_code <= 319) SELECT level, host, PERCENTILE_APPROX(status_code, 0.95) AS status_code_p95, SUM(CASE WHEN level = 'DEBUG' THEN status_code ELSE 0 END) AS debug_status_code, MIN(status_code) AS min_status_code, BIT_OR(status_code) AS status_code_bit_or FROM parsed GROUP BY level, host HAVING BIT_OR(status_code) > 1;
